import test from 'node:test';
import assert from 'node:assert/strict';
import { mergeCustomers, listCustomers } from '../src/customers.js';

test('mergeCustomers successfully merges two customers', () => {
  const customers = [
    { id: 'C-001', name: 'Alice', email: 'alice@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Bob', email: 'bob@example.com', country: 'NL', tier: 'silver' },
  ];
  const invoices = [
    { customerId: 'C-001', number: 'INV-2026-0001', status: 'issued' },
    { customerId: 'C-002', number: 'INV-2026-0002', status: 'issued' },
  ];
  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, 1);
  assert.equal(result.value.customers[0].id, 'C-002');
  assert.equal(result.value.invoices.length, 2);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
  assert.equal(result.value.invoices[1].customerId, 'C-002');
});

test('mergeCustomers fromId not found', () => {
  const customers = [
    { id: 'C-001', name: 'Alice', email: 'alice@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Bob', email: 'bob@example.com', country: 'NL', tier: 'silver' },
  ];
  const invoices = [];
  const result = mergeCustomers(customers, invoices, 'C-999', 'C-002');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers intoId not found', () => {
  const customers = [
    { id: 'C-001', name: 'Alice', email: 'alice@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Bob', email: 'bob@example.com', country: 'NL', tier: 'silver' },
  ];
  const invoices = [];
  const result = mergeCustomers(customers, invoices, 'C-001', 'C-999');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers same customer', () => {
  const customers = [
    { id: 'C-001', name: 'Alice', email: 'alice@example.com', country: 'NL', tier: 'gold' },
  ];
  const invoices = [];
  const result = mergeCustomers(customers, invoices, 'C-001', 'C-001');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'SAME_CUSTOMER');
});

test('mergeCustomers with multiple invoices', () => {
  const customers = [
    { id: 'C-001', name: 'Alice', email: 'alice@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Bob', email: 'bob@example.com', country: 'NL', tier: 'silver' },
  ];
  const invoices = [
    { customerId: 'C-001', number: 'INV-2026-0001', status: 'issued' },
    { customerId: 'C-001', number: 'INV-2026-0002', status: 'issued' },
    { customerId: 'C-001', number: 'INV-2026-0003', status: 'issued' },
    { customerId: 'C-002', number: 'INV-2026-0004', status: 'issued' },
  ];
  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 4);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
  assert.equal(result.value.invoices[1].customerId, 'C-002');
  assert.equal(result.value.invoices[2].customerId, 'C-002');
  assert.equal(result.value.invoices[3].customerId, 'C-002');
});

test('mergeCustomers with no invoices', () => {
  const customers = [
    { id: 'C-001', name: 'Alice', email: 'alice@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Bob', email: 'bob@example.com', country: 'NL', tier: 'silver' },
  ];
  const invoices = [];
  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, 1);
  assert.equal(result.value.invoices.length, 0);
});

test('mergeCustomers handles case insensitive ids', () => {
  const customers = [
    { id: 'C-001', name: 'Alice', email: 'alice@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Bob', email: 'bob@example.com', country: 'NL', tier: 'silver' },
  ];
  const invoices = [
    { customerId: 'C-001', number: 'INV-2026-0001', status: 'issued' },
  ];
  const result = mergeCustomers(customers, invoices, 'c-001', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
});

test('mergeCustomers handles spaces in ids', () => {
  const customers = [
    { id: 'C-001', name: 'Alice', email: 'alice@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Bob', email: 'bob@example.com', country: 'NL', tier: 'silver' },
  ];
  const invoices = [
    { customerId: 'C-001', number: 'INV-2026-0001', status: 'issued' },
  ];
  const result = mergeCustomers(customers, invoices, ' c-001 ', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
});

test('mergeCustomers does not mutate input arrays', () => {
  const customers = [
    { id: 'C-001', name: 'Alice', email: 'alice@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Bob', email: 'bob@example.com', country: 'NL', tier: 'silver' },
  ];
  const invoices = [
    { customerId: 'C-001', number: 'INV-2026-0001', status: 'issued' },
  ];
  const originalCustomersLength = customers.length;
  const originalInvoicesLength = invoices.length;
  mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(customers.length, originalCustomersLength);
  assert.equal(invoices.length, originalInvoicesLength);
  assert.equal(customers[0].id, 'C-001');
  assert.equal(invoices[0].customerId, 'C-001');
});

test('mergeCustomers other customers unaffected', () => {
  const customers = [
    { id: 'C-001', name: 'Alice', email: 'alice@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Bob', email: 'bob@example.com', country: 'NL', tier: 'silver' },
    { id: 'C-003', name: 'Charlie', email: 'charlie@example.com', country: 'NL', tier: 'standard' },
  ];
  const invoices = [
    { customerId: 'C-001', number: 'INV-2026-0001', status: 'issued' },
    { customerId: 'C-003', number: 'INV-2026-0003', status: 'issued' },
  ];
  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, 2);
  assert(result.value.customers.some(c => c.id === 'C-002'));
  assert(result.value.customers.some(c => c.id === 'C-003'));
  assert.equal(result.value.invoices[1].customerId, 'C-003');
});

test('mergeCustomers preserves invoice properties', () => {
  const customers = [
    { id: 'C-001', name: 'Alice', email: 'alice@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Bob', email: 'bob@example.com', country: 'NL', tier: 'silver' },
  ];
  const invoices = [
    { customerId: 'C-001', number: 'INV-2026-0001', status: 'issued', total: 10000 },
  ];
  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].number, 'INV-2026-0001');
  assert.equal(result.value.invoices[0].status, 'issued');
  assert.equal(result.value.invoices[0].total, 10000);
});

test('mergeCustomers with actual customer data', () => {
  const allCustomers = listCustomers();
  const customers = allCustomers.slice(0, 2);
  const invoices = [
    { customerId: customers[0].id, number: 'INV-2026-0001', status: 'issued' },
  ];
  const result = mergeCustomers(customers, invoices, customers[0].id, customers[1].id);
  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, 1);
  assert.equal(result.value.customers[0].id, customers[1].id);
  assert.equal(result.value.invoices[0].customerId, customers[1].id);
});

test('mergeCustomers mixed case with normalizeId', () => {
  const customers = [
    { id: 'C-001', name: 'Alice', email: 'alice@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Bob', email: 'bob@example.com', country: 'NL', tier: 'silver' },
  ];
  const invoices = [];
  const result = mergeCustomers(customers, invoices, 'c-001', 'c-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, 1);
  assert.equal(result.value.customers[0].id, 'C-002');
});

test('mergeCustomers reverse direction', () => {
  const customers = [
    { id: 'C-001', name: 'Alice', email: 'alice@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Bob', email: 'bob@example.com', country: 'NL', tier: 'silver' },
  ];
  const invoices = [
    { customerId: 'C-002', number: 'INV-2026-0002', status: 'issued' },
    { customerId: 'C-001', number: 'INV-2026-0001', status: 'issued' },
  ];
  const result = mergeCustomers(customers, invoices, 'C-002', 'C-001');
  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, 1);
  assert.equal(result.value.customers[0].id, 'C-001');
  assert.equal(result.value.invoices[0].customerId, 'C-001');
  assert.equal(result.value.invoices[1].customerId, 'C-001');
});

